// ServerInterface represents all server handlers.
type ServerInterface interface {
	// PostClaimAgent Claim an agent (Web UI)
	// (POST /agent/claim)
	PostClaimAgent(w http.ResponseWriter, r *http.Request)
	// RegisterAgentSelf Agent self-registration (unclaimed)
	// (POST /agent/register)
	RegisterAgentSelf(w http.ResponseWriter, r *http.Request)
	// GetAgentClaimStatus Check agent claim status (polling endpoint)
	// (GET /agent/{agentId}/claim-status)
	GetAgentClaimStatus(w http.ResponseWriter, r *http.Request, agentId AgentId)
	// GetAgentConfiguration Get agent configuration
	// (GET /agent/{agentId}/configuration)
	GetAgentConfiguration(w http.ResponseWriter, r *http.Request, agentId AgentId)
	// SendAgentHeartbeat Send agent heartbeat
	// (POST /agent/{agentId}/heartbeat)
	SendAgentHeartbeat(w http.ResponseWriter, r *http.Request, agentId AgentId)
	// SubmitAgentResults Submit batch monitoring results
	// (POST /agent/{agentId}/results)
	SubmitAgentResults(w http.ResponseWriter, r *http.Request, agentId AgentId)
	// ListAgents List agents
	// (GET /agents)
	ListAgents(w http.ResponseWriter, r *http.Request, params ListAgentsParams)
	// GetAgent Get agent details
	// (GET /agents/{agentId})
	GetAgent(w http.ResponseWriter, r *http.Request, agentId AgentId)
	// Logout User logout
	// (POST /auth/logout)
	Logout(w http.ResponseWriter, r *http.Request)
	// Oauth2Authorize OAuth2 authorization endpoint
	// (GET /auth/oauth2/authorize)
	Oauth2Authorize(w http.ResponseWriter, r *http.Request, params Oauth2AuthorizeParams)
	// Oauth2Callback OAuth2 callback endpoint
	// (GET /auth/oauth2/callback)
	Oauth2Callback(w http.ResponseWriter, r *http.Request, params Oauth2CallbackParams)
	// Oauth2Revoke Revoke a server-managed session token
	// (POST /auth/oauth2/revoke)
	Oauth2Revoke(w http.ResponseWriter, r *http.Request)
	// Oauth2Token Exchange authorization code for a server-managed session token
	// (POST /auth/oauth2/token)
	Oauth2Token(w http.ResponseWriter, r *http.Request)
	// AuthRefresh Refresh a server-managed session token
	// (POST /auth/refresh)
	AuthRefresh(w http.ResponseWriter, r *http.Request)
	// GetUserInfo Get current user information
	// (GET /auth/userinfo)
	GetUserInfo(w http.ResponseWriter, r *http.Request)
	// PurgeSessions Purge all other sessions
	// (DELETE /sessions)
	PurgeSessions(w http.ResponseWriter, r *http.Request)
	// ListSessions List active sessions
	// (GET /sessions)
	ListSessions(w http.ResponseWriter, r *http.Request)
	// PurgeSession Purge a specific session
	// (DELETE /sessions/{session_id})
	PurgeSession(w http.ResponseWriter, r *http.Request, sessionId UUIDv7)
}

